using System;using System.IO;using System.Linq;using System.Runtime.InteropServices;using Microsoft.Win32;using EnhancedZune;
class PreferenceTests {
 [DllImport("advapi32.dll",CharSet=CharSet.Unicode)]static extern int RegCreateKeyEx(IntPtr key,string sub,int reserved,string cls,int options,int sam,IntPtr security,out IntPtr result,out int disposition);
 [DllImport("advapi32.dll")]static extern int RegOverridePredefKey(IntPtr key,IntPtr newKey);
 [DllImport("advapi32.dll")]static extern int RegCloseKey(IntPtr key);
 static void Check(bool value,string message){if(!value)throw new Exception(message);}
 static int Main(string[] args){string relative=@"Software\EnhancedZune\IsolatedTests\"+Guid.NewGuid().ToString("N");IntPtr root;int disposition;IntPtr hkcu=new IntPtr(unchecked((int)0x80000001));if(RegCreateKeyEx(hkcu,relative,0,null,0,0xf003f,IntPtr.Zero,out root,out disposition)!=0)return 2;try{if(RegOverridePredefKey(hkcu,root)!=0)return 3;UserPreferences.TestRoot=Path.GetFullPath(args[0]);Directory.CreateDirectory(UserPreferences.TestRoot);string target=Path.Combine(UserPreferences.TestRoot,"Zune"),shell=@"Software\Microsoft\Zune\Shell",layers=@"Software\Microsoft\Windows NT\CurrentVersion\AppCompatFlags\Layers",exe=Path.Combine(target,"Zune.exe");Registry.SetValue(@"HKEY_CURRENT_USER\"+shell,"BackgroundImage","personal-background",RegistryValueKind.String);Registry.SetValue(@"HKEY_CURRENT_USER\"+layers,exe,"~ GDIDPISCALING DPIUNAWARE WIN7RTM",RegistryValueKind.String);
  UserPreferences.Apply(target,false,true);Check((string)Registry.GetValue(@"HKEY_CURRENT_USER\"+shell,"BackgroundImage",null)=="personal-background","Existing background changed");Check((string)Registry.GetValue(@"HKEY_CURRENT_USER\"+layers,exe,null)=="~ WIN7RTM HIGHDPIAWARE","Unrelated compatibility flag lost");Check((int)Registry.GetValue(@"HKEY_CURRENT_USER\"+shell,"BackgroundInterfaceTheme",-1)==0,"New interface preference not matched to original white background");Check((int)Registry.GetValue(@"HKEY_CURRENT_USER\"+shell,"InterfaceScalingChoice",-1)==0,"Missing scaling default must be Auto");Check((int)Registry.GetValue(@"HKEY_CURRENT_USER\"+shell,"AlbumArtworkQuality",-1)==0,"Missing artwork default must be Basic");
  Registry.SetValue(@"HKEY_CURRENT_USER\"+shell,"InterfaceScalingChoice",7,RegistryValueKind.DWord);Registry.SetValue(@"HKEY_CURRENT_USER\"+shell,"AlbumArtworkQuality",2,RegistryValueKind.DWord);Registry.SetValue(@"HKEY_CURRENT_USER\"+shell,"BackgroundInterfaceTheme",1,RegistryValueKind.DWord);
  UserPreferences.Apply(target,false,true);Check((int)Registry.GetValue(@"HKEY_CURRENT_USER\"+shell,"InterfaceScalingChoice",-1)==7&&(int)Registry.GetValue(@"HKEY_CURRENT_USER\"+shell,"AlbumArtworkQuality",-1)==2&&(int)Registry.GetValue(@"HKEY_CURRENT_USER\"+shell,"BackgroundInterfaceTheme",-1)==1,"Explicit display preferences were overwritten");
  using(RegistryKey k=Registry.CurrentUser.OpenSubKey(shell,true)){k.DeleteValue("InterfaceScalingChoice");k.DeleteValue("AlbumArtworkQuality");k.DeleteValue("BackgroundInterfaceTheme");}UserPreferences.Apply(target,false,true);
  int count=Directory.GetFiles(UserPreferences.TestRoot,"*.json").Length;UserPreferences.Apply(target,false,true);Check(Directory.GetFiles(UserPreferences.TestRoot,"*.json").Length==count,"Repeat setup added a redundant settings backup");
  UserPreferences.Apply(target,true,true);Check((int)Registry.GetValue(@"HKEY_CURRENT_USER\"+shell,"InterfaceScalingChoice",-1)==0,"Recommended auto scaling missing");Check((int)Registry.GetValue(@"HKEY_CURRENT_USER\"+shell,"AlbumArtworkQuality",-1)==0,"Reset must choose Basic artwork");UserPreferences.Restore(target);Check((string)Registry.GetValue(@"HKEY_CURRENT_USER\"+shell,"BackgroundImage",null)=="personal-background","Original background not restored");Check((string)Registry.GetValue(@"HKEY_CURRENT_USER\"+layers,exe,null)=="~ GDIDPISCALING DPIUNAWARE WIN7RTM","Original compatibility flags not restored");Check(Registry.GetValue(@"HKEY_CURRENT_USER\"+shell,"BackgroundInterfaceTheme",null)==null,"Missing preference was not removed on restore");
  UserPreferences.Apply(target,true,true);Registry.SetValue(@"HKEY_CURRENT_USER\"+shell,"BackgroundImage","later-user-choice");UserPreferences.Restore(target);Check((string)Registry.GetValue(@"HKEY_CURRENT_USER\"+shell,"BackgroundImage",null)=="later-user-choice","Later user setting overwritten");File.WriteAllText(Path.Combine(UserPreferences.TestRoot,"results.txt"),"PASS: process-private registry — preserved existing appearance; preserved unrelated DPI flags; matched missing interface preference; no-op repeat; restored missing values and all settings batches; retained later user choice. No real Zune registry paths modified.");Console.WriteLine(File.ReadAllText(Path.Combine(UserPreferences.TestRoot,"results.txt")));return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}finally{RegOverridePredefKey(hkcu,IntPtr.Zero);RegCloseKey(root);Registry.CurrentUser.DeleteSubKeyTree(relative,false);}}
